#!/usr/bin/env node
// Differential fuzz of the help / usage layout across COLUMNS.
import { report } from '/tmp/difftest.mjs';

const widths = [];
for (let n = 1; n <= 120; n += 1) widths.push(String(n));
widths.push('121', '150', '200', '500', '10000');
const malformed = ['', '0', '-5', 'abc', '30x', ' 30 ', '+30', '3_0', '３０'];

const argvSets = [
  ['--help'],
  ['-h'],
  ['--a', '1'],
  [],
  ['--a', 'x', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--z'],
];

const cases = [];
for (const columns of [...widths, ...malformed]) {
  for (const argv of argvSets) {
    cases.push({ argv, env: { COLUMNS: columns } });
  }
}

console.log(`running ${cases.length} cases`);
const failures = report(cases);
process.exit(failures === 0 ? 0 : 1);
